\section{System Model} \label{System_model}

\begin{figure}[t]
\centering
\includegraphics[width = 0.30\textwidth]{D2D_topology.eps}
\caption{System scenario}
\label{Fig:D2D_topology}
\end{figure}

As shown in Fig.~\ref{Fig:D2D_topology}, a DL shared HetNet is considered, where a number of equipments coexist such as potential DUEs and conventional BSs.
In this network, the time division duplexing (TDD) mechanism is adopted.
% The DUEs are assumed to be served in pairs according to the result in \cite{2014_Ye_analysis}, e.g., a DUE is served by the other DUE in the same D2D pair.
The sets of BSs and DUEs are denoted as $\mathcal{B}$ and $\mathcal{U}$, respectively. 
Meanwhile, we define $B:=|\cal{B}|$ and $U:=|\cal{U}|$.
Each DUE is assumed to be able to act as a multi-hop relay or a user. For instance, it can act as a user to receive data from BSs or other DUEs in one time slot, and a relay to help other DUEs in poor channel states in another time slot.
% bad-connected DUEs in another time slot.
Therefore, we assume that each DUE can choose either to be a user or a server in different time slots and is decoupled into both roles. Specifically, the server set $\mathcal{N}$ including both BSs and DUEs is defined as follows:
\begin{eqnarray}
  \mathcal{N} &:=& \{ \underbrace{1,\cdots,B}_{\sf BSs}, \underbrace{{B + 1}, \cdots , {B + U}}_{\sf potential~DUEs} \}.
  \label{Eq:transmitter} 
  % \mathcal{U} &:=& \{ \underbrace{1,\cdots,C}_{\sf CUEs}, \underbrace{{C + 1}, \cdots, {C + 2D}}_{\sf DUEs} \}.
  % \label{Eq:receiver}
\end{eqnarray}

A vector $\bm{v}_i = [v_{i,1},\cdots,v_{i,N}]^T$ is employed to indicate the active status of the servers in one time slot and defined as the time reuse pattern, where $N :=|\mathcal{N}|$ is the number of servers.
Each element of the time reuse pattern $\bm{v}_i$ is determined as $v_{i,n} = 1$ if server $n$ is active in the time slot $i$, and $v_{i,n} = 0$ otherwise.
Define the index of patterns as $\mathcal I = \{1,\cdots,2^N-1\}$, then there are totally $|\mathcal I| = 2^N-1$ valid time reuse patterns to be considered since each possible time reuse pattern $\bm{v}_i$ has the potential to enhance the time resource utilization.
The total pattern set is denoted as $\tilde{\mathcal{V}} = \{ \bm{v}_i | i \in \mathcal I \}$.
Besides, we pick out the active servers under pattern $\bm v_i$ and use $\mathcal{A}_i$ to denote the set of these servers as $ \mathcal{A}_i = \{ n | v_{i,n} = 1, n \in \mathcal N \}$.
% \begin{equation}
%   \mathcal{A}_i = \{ n | v_{i,n} = 1, n \in \mathcal N \}.
%   \label{Eq:active_set}
% \end{equation}
Let $x_i$ denote the fraction of the total available TDD frame duration $T$ allocated to time reuse pattern $\bm v_i$.
The overall time reuse profile is thus given by the vector: $\bm{x} := [x_1,\cdots,x_{2^N-1}]^T$.
To realize the optimal performance, we should make full use of the whole available time, which means that $\sum_{i\in \mathcal I} x_i = 1$. 
Furthermore, assuming that each server can not transmit data to two users simultaneously, a server need to divide the nonoverlapping time resource under pattern $\bm v_i$ to its users.
We define $y_{u,n,i} \geq 0$ to denote the fraction of the total TDD duration $T$ allocated to user $u$ by server $n$ under pattern $\bm v_i$, which is bounded as
$\sum_{u\in \mathcal U} y_{u,n,i}\leq x_i$.
% Clearly, the total time resource available for server $n$ under pattern $\bm v_i$ is bounded by $x_i$, i.e.
% \begin{equation}
% \sum_{u\in \mathcal U} y_{u,n,i}\leq x_i,   n\in \mathcal N,   i\in\mathcal I.
% \end{equation}
Additionally, each user is forced to be associated to a single server in each time slot, which is indicated by $z_{u,n,_i}$, e.g. $z_{u,n,i}=1$ when user $u$ is served by server $n$ in time slot $i$, and $z_{u,n,i}=0$ otherwise.  
Due to the single-association principle, the variable set $\{ z_{u,n,i} \}$ satisfies the constraint $\sum_{n \in \mathcal{N}} z_{u,n,i} = 1$.

Apart from these assumptions, we also assume a flat power spectrum density (PSD) for each server, e.g. $P_n$ is the PSD of server $n$. 
The signal-to-interference-plus-noise ratio (SINR) of the link between user $u$ and server $n$ under time reuse pattern $\bm v_i$ is denoted as $\gamma_{u,n,i}$ and calculated as 
\begin{equation}
\label{eq:gamma}
  \gamma_{u,n,i} =
  \frac{\mathds{1}\{ n\in \mathcal{A}_i \} P_n |g_{n,u}|^2}
  {\sigma^2 + \sum_{m \in \mathcal{A}_i, m\neq n } P_{m} |g_{m,u}|^2 },
\end{equation}
where $\sigma^2$ is the PSD of the thermal noise at the user and $g_{n,u}$
denotes the gain of the channel from server $n$ to user $u$.
Moreover, the spectral efficiency $c_{u,n,i}$ is calculated based on the corresponding SINR.
With the assumption that one DUE can not transmit and receive data simultaneously, the $c_{u,n,i}$ need to be zero if server $(u+B)$ is active under pattern $\bm v_i$.
  Therefore, the spectral efficiency can be calculated as follows:
  \begin{equation}
    c_{u,n,i} = \mathds{1}\{ (u+B) \not\in \mathcal{A}_i \}  \cdot \log_2 (1 + \gamma_{u,n,i}).
  \end{equation}

Note that the actual time resource allocated to user $u$ by server $n$ under pattern $\bm v_i$ in each frame is $Ty_{u,n,i}$, then the average rate of user $u$ over $T$ is written as follows: 
\begin{equation}
\begin{split}
	R_u & = \frac{1}{T} \cdot W \cdot \sum_{i\in\mathcal I} \sum_{n\in\mathcal N} z_{u,n,i} \cdot T \cdot  y_{u,n,i} \cdot c_{u,n,i}\\
	& = W \cdot \sum_{i\in\mathcal I} \sum_{n\in\mathcal N} z_{u,n,i}  \cdot  y_{u,n,i} \cdot c_{u,n,i},
\end{split} 
\end{equation}
where $W$ is the system bandwidth.
The single-server association rule results in a combinatorial problem and finding an optimal solution need the exhaustive method.
Therefore, in the next section, we allow one user to be served by multiple servers firstly, which will enable low-complexity algorithms to find the optimal reuse profile.

\section{Problem Formulation} \label{Formulation}

\subsection{Original Problem}
The network utilization is measured by the PF of DUE effective rates through judiciously selecting the time reuse patterns. 
Thus the original problem is formulated in (\ref{Eq:original_problem}), 
\begin{figure}
\setcounter{mytempeqncnt}{\value{equation}}
\begin{subequations}
\label{Eq:original_problem}
\begin{align}
    \underset{\bm{x},\bm{y},\bm{z}}{\rm maximize}\quad  & \sum_{u \in \mathcal U} \log (R_u)\label{Eq:PF_metric} \\
    {\rm subject\ to} \quad 
    & \bar R_u =  W \sum_{i\in\mathcal I} \sum_{n\in\mathcal N} z_{u,n,i} \cdot y_{u,n,i} \cdot c_{u,n,i}, \forall  u\\
    % &  R_{u,n} =  W \sum_{i\in\mathcal I}  z_{u,n} \cdot y_{u,n,i} \cdot c_{u,n,i},  u \in \mathcal{U},  n \in \mathcal{N}\\
    &\tilde R_n =  W \sum_{i\in\mathcal I} \sum_{u\in\mathcal U} z_{u,n,i} \cdot y_{u,n,i} \cdot c_{u,n,i},  \forall  n \\
    & R_u = \bar R_u - \tilde R_{u+B} , \forall  u \label{Eq:Rate}\\
    &\sum_{n\in \mathcal N} z_{u,n,i} = 1,z_{u,n,i} \in \{ 0, 1\}, \forall u,n,i\\
    & x_i \geq \sum_{u\in \mathcal U} z_{u,n,i} \cdot y_{u,n,i}, \forall n,i\\
    & \sum_{i\in\mathcal I} x_i = 1,  x_i \geq 0, \forall i, \ y_{u,n,i} \geq 0,  \forall u,n,i\label{Eq:x_y_constraints}
\end{align}
\end{subequations}
\hrulefill
\end{figure}
where the optimization variables $\bm x$, $\bm y$, $\bm z$ denote the overall time reuse profile: $\{x_i, \forall i\}$, the overall user time
allocation profile $\{y_{u,n,i}, \forall u, n, i\}$, and the DUE association profile $\{z_{u,n,i},\forall u, n, i\}$
respectively.
Problem (\ref{Eq:original_problem}) turns out to be a large scale knapsack problem,
which is NP-hard to find its optimal solution.
In next section, we will relax it to enable low-complexity solution.

\subsection{Relaxed Problem}

By allowing fractional user association, we can drop the single-server association indicator variable $\bm{z}$ and rely on $\bm y$ to indicate the association profile.
Particularly, given $y_{u,n,i} > 0$, we can infer the $u$-th user is served by the $n$-th server under pattern $\bm v_i$. 
The relaxed multi-server association problem is shown in (\ref{Eq:relaxed_problem}), whose solution offers an upper bound of the problem in (\ref{Eq:original_problem}).
The objective function in (\ref{Eq:relaxed_problem}) is concave and all the constraints are linear. 
However, the amount of variables, i.e. $\{x_i\}$ and $\{y_{k,n,i}\}$, increases exponentially with the number of servers due to the fact that we have $2^N-1$ different time reuse patterns. 
For a large HetNet, it is a formidable task to obtain a solution to the problem in (\ref{Eq:relaxed_problem}).
Fortunately, we can show that only a very limited number of reuse patterns need to be activated without sacrificing the network throughput.

% \begin{figure}
% \setcounter{mytempeqncnt}{\value{equation}}
\begin{subequations}
\label{Eq:relaxed_problem}
  \begin{align}
    \underset{\bm{x},\bm{y}}{\rm maximize}\quad  
    & \mathcal P(\bm y) =  \sum_{u\in\mathcal U} \log (R_u) \label{Eq:object_1} \\
    {\rm subject\ to} \quad 
    & \bar R_u =  W \sum_{i\in\mathcal I} \sum_{n\in\mathcal N}  y_{u,n,i} \cdot c_{u,n,i},  \forall u \label{Eq:RateReceive}\\
    &\tilde R_n =  W \sum_{i\in\mathcal I} \sum_{u\in\mathcal U}   y_{u,n,i} \cdot c_{u,n,i},  \forall n\label{Eq:RateSend}\\
    & R_u = \bar R_u - \tilde R_{u+B} \\
    & \sum_{i\in\mathcal I} x_i = 1, x_i \geq 0, \forall i \label{Eq:constraint_totalresource}\\
    & x_i \geq \sum_{u\in\mathcal U} y_{u,n,i},\forall i, ~y_{u,n,i} \geq 0, \forall u,n,i\label{Eq:constraint_pattern}
  \end{align}
\end{subequations}
% \hrulefill
% \end{figure}



\begin{pro}
\label{Pro:pattern_number}
There exists one optimal solution to the problem in (\ref{Eq:relaxed_problem}) where
at most $2U$ out of $2^N - 1$ reuse patterns are active. 
Specifically, we can find one time reuse profile $\bm x^*$ which maximizes the objective function
in (\ref{Eq:relaxed_problem}) and satisfies the following criterion:
\begin{equation}
    \label{Eq:pattern_number}
    \lVert \bm{x}^* \rVert_0 \leq 2U.
  \end{equation}
\end{pro}
\begin{proof}
Suppose that there is one particular optimal $\bm x$ and $\bm y$, and each element of $\bm y$ can be split into two parts to extract $x_i$ by defining $\tau_{u,n,i}$, i.e. $y_{u,n,i} = x_i \cdot\tau_{u,n,i}$. The data rates $\bar R_u$ and $\tilde R_n$ in (\ref{Eq:RateReceive}) and (\ref{Eq:RateSend}) turn to be 
\begin{equation}
\label{Eq:rate_split}
  \bar R_u = W \sum_{i\in\mathcal I} x_i \bar R_u^i,   ~  \tilde R_n  = W \sum_{i\in\mathcal I} x_i \tilde R_n^i,
\end{equation}
where
\begin{equation}
  \bar R_u^i = W \sum_{n\in\mathcal N}  \tau_{u,n,i} \cdot c_{u,n,i},~ \tilde R_n^i = W \sum_{u\in\mathcal U}  \tau_{u,n,i} \cdot c_{u,n,i}.
\end{equation}
Let $\bar{\bm R} = [\bar R_1,\cdots,\bar R_U]^T$, $\tilde{\bm R} = [\tilde R_1,\cdots,\tilde R_U]^T$, $\bar{\bm R}^i = [\bar R_1^i,\cdots,\bar R_U^i]^T$, $\tilde{\bm R}^i = [\tilde R_{B+1}^i,\cdots,\tilde R_N^i]^T$, and  $\bm \Psi^i = [\bar{\bm R}^{iT}, \tilde{\bm R}^{iT}]^T$.
For a particular ${\bm R} = [ R_1,\cdots, R_U]^T = \bar{\bm R} - \tilde{\bm R}$, we can construct an auxiliary variable $\bm \Psi = [\bar{\bm R}^T, \tilde{\bm R}^T]^T$, which is also a convex combination as follows:
\begin{equation}
  \bm \Psi = \left[\begin{matrix}
    \bar{\bm R}^1,\cdots,\bar{\bm R}^{2^N-1}\\ \tilde{\bm R}^1,\cdots,\tilde{\bm R}^{2^N-1}
  \end{matrix}\right]\bm x = 
  \left[{\bm \Psi}^1,\cdots,{\bm \Psi}^{2^N-1} \right]\bm x 
  .
\end{equation}
Thus $\bm \Psi $ lies in the convex hull of $\mathcal Q$, i.e. ${\sf conv}(Q)$, where $\mathcal Q = \{\bm \Psi^i\}_{i\in\mathcal I}$.
Additionally, from the Carath\'{e}odory's Theorem \cite{2006_Nonlinear_Programming},
$\bm \Psi$ must lie in the convex hull of $(2U+1)$  affinely independent points since the dimension of $\bm \Psi$ is $2U$. Let $\mathcal Q'$ denote the set of these particular points, then $\bm \Psi$ lies in the convex hull of $\mathcal Q'$, i.e. ${\sf conv}(Q')$, which is a $2U$-simplex. 
Furthermore, the optimal $\bm \Psi^* = [\bar{\bm R}^{*T}, \tilde{\bm R}^{*T}]^T$ should reach the Pareto efficiency \cite{2015_Zhuang}\cite{1997_Linear_Programming} since the network utilization is measured by the PF (\ref{Eq:object_1}), which is concave with respect to $(\bar{\bm R} -\tilde{\bm R} )$. 
Then we can find one optimal solution on the face of $2U$-simplex, which is a $(2U-1)$-simplex as well. Hence, $\bm \Psi^*$ can be represented by a convex combination of at most $2U$ affinely independent points in ${\sf conv}(\mathcal Q)$, and the optimal $\bm R^*$ can be obtained as $\bm R^* = [\bm I ,-\bm I]\bm \Psi^*$, where $\bm I$ is a $U\times U$ identity matrix.
Therefore, for both $\bm \Psi^*$ and $\bm R^*$,  there exits one optimal time reuse profile $\bm x^*$ satisfying $\|\bm x^*\|_0 \le 2U $.
\end{proof}
Proposition \ref{Pro:pattern_number} indicates that we only need no more than $2U$ active time reuse patterns to achieve the optimal network utilization instead of activating all $2^N-1$ patterns.


\section{Efficient Algorithm}\label{Algorithms}
As is indicated in Proposition \ref{Pro:pattern_number}, the following optimization problem has same objective value as the problem in (\ref{Eq:relaxed_problem}).
\begin{subequations}
\label{Eq:problem_coordinate}
  \begin{align}
    \underset{\bm{x},\bm{y},\mathcal V}{\rm maximize}\quad  
    & \mathcal P(\bm y, \mathcal V) = \sum_{u\in\mathcal U}\log (R_u)   \\
    {\rm subject\ to} \quad 
    &  x_i = 0,  i\in \{i| \bm v_i\notin \mathcal V\},\label{Eq:ZeroPat}\\
    & |\mathcal V| \le 2U, \label{Eq:NumPat}\\
    &{\rm (\ref{Eq:RateReceive})-(\ref{Eq:constraint_pattern})}\label{Eq:OtherConstr},
  \end{align}
\end{subequations}
where $\mathcal V \subseteq \tilde{\mathcal V} $ is the candidate pattern set. Although this problem is still formidable to solve, it can be settled by solving two subproblems iteratively:
 % according to the well-known block coordinate descent method (BCD).

\noindent{$\bullet$} Pattern selection: Find the candidate pattern set $\mathcal{V}^{t+1}$ satisfying
\begin{equation}
  \label{Eq:Sub_1}
    \mathcal{V}^{t+1} \subseteq \tilde{\mathcal{V}},\ \lvert \mathcal{V}^{t+1} \rvert \leq 2U.
  \end{equation}
\noindent{$\bullet$} Resource allocation under particular patterns:
  \begin{eqnarray}\label{Eq:Sub_2}
    \underset{\bm{x},\bm{y}}{\rm maximize}\ \mathcal P(\bm y, \mathcal V^{t+1}), \ {\rm subject \ to} \ {\rm (\ref{Eq:ZeroPat}) \ and \ (\ref{Eq:OtherConstr}}).
  \label{Eq:sub_2}
\end{eqnarray}

The problem in (\ref{Eq:Sub_2}) is convex, and it can be solved efficiently by general convex solvers, e.g. CVX \cite{2015_CVX}, comparing with the brute-force method to solve the problem with all $2^N-1$ possible patterns directly.
However, the pattern selection problem has $\sum_{m=1}^{2U} \binom{2^N-1}{m} $ possible solutions, of which the exhaustive search method is infeasible.
% is a combinatorial optimization problem and the exhaustive search is not feasible when $N$ is large.
An efficient pattern selection algorithm is urgent.

\subsection{Semi-distributed Pattern Selection (SDPS) Algorithm}
Solving the pattern selection problem directly is NP-hard, thus we try to find an approximated solution with low-complexity.  
In order to make full use of the information of the previous candidate pattern set $\mathcal{V}^t$, we define a set $\mathcal{V}_d^t$ as 
  \begin{equation}
      \mathcal{V}_d^t = \{ \bm{v} \big|  d_H(\bm{v},\bm{v}') \leq d, \bm{v}' \in \mathcal{V}^t\}, d \in \mathcal N,
  \end{equation}
   where $d_H(\bm{v},\bm{v}')$ denotes the Hamming distance between $\bm{v}$ and $\bm{v}'$. 
We further assume to only add a few patterns to the candidate pattern set $\mathcal{V}$ in the $t$-th iteration when $|\mathcal V^t|< 2U$, i.e. $\mathcal{V}^{t+1} = \mathcal V^t \bigcup \mathcal V^*$, where $\mathcal V^*\subseteq \mathcal V_d^t $ is a particular pattern set need to be involved in the next iteration.
Let $\mathcal{G(V)} = \{ \bm{x} | \sum_{i\in \{i| \bm v_i\in \mathcal V\}} x_i = 1; x_i \geq 0, \forall i\}$ and $\mathcal F(\bm x) = \{ \bm{y} | \sum_{u} y_{u,n,i} = x_i, y_{u,n,i} \geq 0, \forall u,n,i\}$,
an iterative pattern selection method inspired by the Frank-Wolfe method in \cite{2006_Nonlinear_Programming} and the pattern selection approach in \cite{2016_Kuang} is put forward as follows:
\begin{equation}
\label{Eq:MM_update_D2D}
(\mathcal{\bar V}, \bar{\bm{x}} ,\bar{\bm{y}}) =
\arg \max_{{\mathcal{V}}\subseteq \mathcal V_d^t} \max_{\bm{x} \in \mathcal{G(V)}} \max_{\bm{y} \in \mathcal{F}(\bm{x}) }
    \nabla_{\bm{y}} \mathcal P (\bm{y}^t)^T \bm{y}.
\end{equation}
Expression (\ref{Eq:MM_update_D2D}) indicates that one suitable pattern set can be found by finding the direction realizing the most predominant improvement of the objective function under some constraints. Let $p_{\bar u,\bar n, \bar i}^t := [\nabla_{\bm{y}} \mathcal{P}(\bm{y}^t)]_{\bar u, \bar n, \bar i}$ denote the $(\bar u, \bar n,\bar i)$-th entry of the gradient vector, where $p_{\bar u,\bar n, \bar i}^t $ is derived as follows: 
\begin{equation}
  p_{\bar u,\bar n, \bar i}^t = W \cdot c_{\bar u,\bar n,\bar i} \cdot \left(  R_{\bar u}^{-1} - \mathds{1}\{ \bar n > B \} \cdot R_{\bar n - B}^{-1} \right).
\end{equation}
% \begin{equation}
% p_{\bar u,\bar n, \bar i}^t = \begin{cases}
%    W \cdot c_{\bar u, \bar n, \bar i} \frac{R_{\bar n-B} - R_{\bar u}}{ R_{\bar u} R_{\bar n-B} }  , & \bar n>B\\
%   W \cdot c_{\bar u, \bar n, \bar i} \frac{ 1 }{ R_{\bar u}  }  , & {\sf otherwise}.
% \end{cases} 
% \end{equation}
 We have the following proposition:

\begin{pro}\label{Pro_choosepattern}
The optimal pattern candidate set in the $t$-th iteration must contain one particular pattern $\bm{v}_{i^*}$ with the largest gain over the other patterns.
The $\bm{v}_{i^*}$ is selected as follows:
% One suitable pattern with the largest gain over the other patterns in the $t$-th iteration according to (\ref{Eq:MM_update_D2D}) is selected as follows:
\begin{equation}
\label{Eq:pro_2}
 \bm v_{i^*} = \arg \max_{\bm v_i\in \mathcal V_d^t}
 \sum_{n\in\mathcal N} p_{u_{n,i}^*,n,i}^t.
\end{equation}
where $u_{n,i}^*$ stands for the user obtaining the largest gain from server $n$
under reuse pattern $i$, i.e. $u_{n,i}^* = \arg \max_u \ p_{u,n,i}^t$.
\end{pro}
\begin{proof}
Let $y_{u,n,i} = x_i \cdot\tau_{u,n,i}$ in (\ref{Eq:MM_update_D2D}). The ranges of summation and maximization with respect to $u$, $n$ and $i$ are set as $u\in\mathcal U$, $n\in\mathcal N$ and $i\in\mathcal I$ by default. 
The problem becomes
\begin{equation}
\label{Eq:inner_product}
\underset{\underset{|\mathcal V| \le 2U}{{\mathcal{V}}\subseteq \mathcal V_d^t}} {\rm max} ~
\underset{ \underset{x_i \geq 0}{ \sum_i x_i = 1} }{\rm max}
\sum_{i\in\{i|\bm v_i\in \mathcal V\}} x_i \sum_n \ \underset{ \underset{\tau_{u,n,i}\geq 0}{\sum_u \tau_{u,n,i} = 1} }
{\rm max} \sum_u \tau_{u,n,i} \cdot p_{u,n,i}^t.
\end{equation}
The third maximization is a constrained linear programming (LP) problem and the
optimal solution $\tau_{u,n,i}^*$ is given by
\begin{equation}
\label{Eq:choose_user}
\tau_{u,n,i}^* = \mathds{1}\{u = u^*_{n,i}\}, \ u^*_{n,i} = \arg \max_u p_{u,n,i}^t.
\end{equation}
Then (\ref{Eq:inner_product}) becomes equivalent to
\begin{equation}
\label{Eq:changed_inner}
\underset{\underset{|\mathcal V| \le 2U}{{\mathcal{V}}\subseteq \mathcal V_d^t}} {\rm max}  ~
\underset{ \underset{x_i \geq 0}{ \sum_i x_i = 1} }{\rm max}
\sum_{i\in\{i|\bm v_i\in \mathcal V\}} x_i \sum_n p_{u_{n,i}^*,n,i}^t.
\end{equation}
The second maximization is also a LP problem exhibiting the following solution:
\begin{equation}
\label{Eq:choose_pattern}
\bar{x_i} = \mathds{1}\{i = i^*_\mathcal{V} \}, \ i^*_\mathcal{V} = \arg \max_{i\in\{i|\bm v_i\in \mathcal V\}} \sum_n p_{u^*_{n,i},n,i}^t.
\end{equation}
Then the problem becomes equivalent to
\begin{equation}
  \underset{\underset{|\mathcal V| \le 2U}{{\mathcal{V}}\subseteq \mathcal V_d^t}} {\rm max}  \  \sum_n p_{u_{n,i^*_\mathcal{V}}^*,n,i^*_\mathcal{V}}^t.
\end{equation}
Let 
\begin{equation}
  \bm v_{i^*} = \arg \max_{\bm v_i\in \hat{\mathcal V}_d}
 \sum_{n\in\mathcal N} p_{u_{n,i}^*,n,i}^t,
\end{equation} 
the solution $\bar{\mathcal{V}}$ of (\ref{Eq:MM_update_D2D}) should contain the particular pattern $\bm{v}_{i^*}$ to maximize the objective value.
\end{proof}

According to Proposition \ref{Pro_choosepattern}, the complexity of finding the candidate pattern set $\mathcal{V}^{t+1}$ is determined by the size of $\mathcal{V}_d^t$ in $t$-th iteration.
% The main complexity of the proposed pattern selection method is concentrated on $|\hat{\mathcal V}_d|$ according to Proposition \ref{Pro_choosepattern}.   
 In particular, we set $d = 1$ for the lowest complexity in the pattern selection subproblem, which suggests that each server is aware of the status of the others while it can only decide its own occupation status. 
 Additionally, $d=1$ enables the semi-distributed pattern selection method, where server-$n$ can choose one $\bm{\nu}_{n,i^*}$ from the candidate pattern set $\mathcal V_n^t = \{ {\bm \nu}_{n,i}^{t,w}|{\bm v_i^{t}\subseteq \mathcal V^{t}}, w = 0,1\}$, and $\bm \nu^{t,w}_{n,i} \triangleq \bm v_{i}^t \circ (\bm 1 - \bm e_n) + w \bm e_n$.
% \begin{equation}
%   \bm \nu^{t,w}_{n,i} \triangleq \bm v_{i}^t \circ (\bm 1 - \bm e_n) + w \bm e_n.
% \end{equation}
 Hence $\mathcal V^{t+1}$ is updated as follows:
  \begin{equation}
    \mathcal{V}^{t+1} = \mathcal V^t \cup \{\bm \nu_{n,i^*}\}_{n\in\mathcal N},
  \end{equation}
 where $\bm{\nu}_{n,i^*}$ is chosen according to 
  \begin{equation}
  \label{Eq:prop2_distr}
    \bm \nu_{n,i^*} = \arg \underset{ {\bm \nu_{n,i}\in \hat{\mathcal V}_n^t} }{\rm max} \sum_{\bar n\in\mathcal N} p_{u_{\bar n,i}^*,\bar n,i}^t.
  \end{equation}
  The patterns selected according to (\ref{Eq:prop2_distr}) are valid and satisfy the requirement in (\ref{Eq:pro_2}) since $\mathcal V_d^t|_{d=1} = \bigcup_{n\in\mathcal N} \mathcal V_n^t$.

Furthermore, the cardinality of $\mathcal{V}_n^t$ can be further reduced noticing that the pattern is meaningless if $\bm{\nu}_{n,i}^{t,w} \in \mathcal V^t$. Therefore, the candidate pattern set of server-$n$ is modified as 
  \begin{equation}
  \label{Eq:modify_pat_set}
    \mathcal V_n^t = \{ {\bm \nu}_{n,i}^{t,w}|{\bm v_i^{t}\subseteq \mathcal V^{t}}, w = 1 - v_{i,n}^{t} \}.
  \end{equation}
 To ensure some new reuse patterns get activated in the $t$-th iteration, we modify the rule in (\ref{Eq:prop2_distr}) as follows:
% For the same reason, we also require $\bm \nu_{n,i}\notin\mathcal{V}^{t}$. 
% Finally, 
% $\bm{\nu}_{n,i^*}$ is chosen according to 
  \begin{equation}
  \label{Eq:modified_prop2_distr}
    \bm \nu_{n,i^*} = \arg \underset{ \bm \nu_{n,i}\notin\mathcal{V}^{t},{\bm \nu_{n,i}\in \mathcal V_n^t} }{\rm max} \sum_{\bar n\in\mathcal N} p_{u_{\bar n,i}^*,\bar n,i}^t.
  \end{equation}
\subsection{Efficient Algorithms Summary}
Note that the solution obtained by solving (\ref{Eq:problem_coordinate}) allows multi-server association.
To meet the single-server association requirement in (\ref{Eq:original_problem}),
we can simply associate the user to the server that gives the largest data rate
under the particular reuse pattern $\bm{v}_i$, i.e.
\begin{equation}
\label{Eq:multi_2_single}
z_{u,n,i} = \mathds{1}\{n = n_{u,i}^*\}, \ n_{u,i}^* = \arg \max_{n\in\mathcal N}  ~y_{u,n,i} \cdot c_{u,n,i}.
\end{equation}

After finalizing the user association rule, the time resources need to be
re-allocated among all the active reuse patterns in $\mathcal{V}^{t}$ to solve the
original problem in (\ref{Eq:original_problem}).
Algorithm \ref{Alg:solve_MM} summarizes all the steps.

\begin{algorithm}[t]
\caption{Optimal Time Reuse with SDPS}
\begin{algorithmic}[1]
\State \textbf{Initialization:}
  Initialize $\epsilon_1=\epsilon_2=10^{-4}$, $\bm{x}^1$, $\bm{y}^1$, $\mathcal V^1$, and $\mathcal{P}^1$;
\State \textbf{Repeat}
\State \quad\textbf{For} server $n\in \mathcal N$ (in parallel)
\State \quad\quad Obtain pattern set $ \hat{\mathcal V}_n^t $ according to (\ref{Eq:modify_pat_set});
\State \quad\quad Choose pattern $\bm \nu_{n,i^*}$ from $\hat{\mathcal V}_n^t$ according to (\ref{Eq:modified_prop2_distr});
\State \quad\textbf{End} 
\State \quad Renew $\mathcal{V}^t$ as $\mathcal{V}^{t+1} = \mathcal V^t \cup \{\bm \nu_{n,i^*}\}_{n\in\mathcal N}$;
\State \quad Solve (\ref{Eq:sub_2}) with $\mathcal{V}^{t+1}$, obtain $\bm x^{t+1}$, $\bm y^{t+1}$ and $\mathcal P^{t+1}$;
\State \quad $\mathcal V^{t+1} = \{\bm v^{t+1}_i| x^{t+1}_i>\epsilon_2\}$;
\State \quad $t = t + 1$;
\State \textbf{Until} $|\mathcal{P}^t - \mathcal{P}^{t-1}| < \epsilon$ or $|\mathcal{V}^{t}| > 2U$;
\State Determine the single-server association as in (\ref{Eq:multi_2_single});
\State Solve (\ref{Eq:original_problem}) with the patterns in $\mathcal{V}^t$ and the
determined association rule, obtain the single-server association solution.
\end{algorithmic}
\label{Alg:solve_MM}
\end{algorithm}

\section{Numerical Results} \label{Simulation}


In this section, the proposed algorithm is tested by simulating a HetNet with $1$ pico-BS ($30$dBm transmission power (TxPwr)) and a number of DUEs ($20$dBm TxPwr). The others are set as follows:\\
\noindent{$\bullet$} DUEs are uniformly dropped in a square specified by $[0,200]$m$\times [0,200]$m and the pico-BS is deployed at the center;\\
\noindent{$\bullet$} System bandwidth is $20$MHz. Noise PSD is $-174$dBm/Hz. The
path-losses for all links are: $37.6 \log_{10} d_m + 35.3$ (dB) \cite{2016_Ma_HenNet_D2D}, where $d_m$ is the distance in terms of meters. The log-normal shadowing is assumed with a standard deviation $8$dB;
% \noindent{$\bullet$} Both thresholds are set as $\epsilon_1 = \epsilon_2 = 10^{-4}$.
